function translateField(value: string | Record<string, string> | undefined): string {
  if (!value) return '';
  if (typeof value === 'object') {
    const lang = (tolgee.value.getLanguage() || 'en').split('-')[0];
    return value[lang] || value['en'] || Object.values(value)[0] || '';
  }
  return value;
}

