};

function batchStatus(batchNum: number): 'pending' | 'running' | 'passed' | 'failed' {
  const batchAgents = agentCards.value.filter(a => a.batch === batchNum);
  if (!batchAgents.length) return 'pending';
  if (batchAgents.some(a => a.status === 'failed')) return 'failed';
  if (batchAgents.some(a => a.status === 'running')) return 'running';
  if (batchAgents.every(a => a.status === 'passed')) return 'passed';
  return 'pending';
}

const activeBatches = computed(() => {
  const batches = new Set(agentCards.value.map(a => a.batch));
  return [1, 2, 3].map(n => ({
    num: n,
    ...BATCH_LABELS[n],
    status: batches.has(n) ? batchStatus(n) : 'pending',
  }));
});

