// Review expiry timer (matches backend _CACHE_TTL = 30 * 60)
const REVIEW_TTL_MS = 30 * 60 * 1000;
let reviewExpiryTimer: ReturnType<typeof setTimeout> | null = null;
let reviewCountdownTimer: ReturnType<typeof setInterval> | null = null;
const reviewRemainingMinutes = ref<number | null>(null);

const REVIEW_STORAGE_KEY = 'sdk_review_state';

function saveReviewState() {
  if (!reviewResult.value) return;
  sessionStorage.setItem(REVIEW_STORAGE_KEY, JSON.stringify({
    reviewResult: reviewResult.value,
    improvements: improvements.value,
    validationStages: validationStages.value,
    agentCards: agentCards.value,
    totalTokens: totalTokens.value,
    importedCardId: importedCardId.value,
    expiresAt: Date.now() + (reviewRemainingMinutes.value ?? 0) * 60 * 1000,
  }));
}

function restoreReviewState() {
  const raw = sessionStorage.getItem(REVIEW_STORAGE_KEY);
  if (!raw) return;
  try {
    const saved = JSON.parse(raw);
    const remainingMs = saved.expiresAt - Date.now();
    if (remainingMs <= 0) {
      sessionStorage.removeItem(REVIEW_STORAGE_KEY);
      return;
    }
    reviewResult.value = saved.reviewResult;
    improvements.value = saved.improvements || [];
    validationStages.value = saved.validationStages || [];
    agentCards.value = saved.agentCards || [];
    totalTokens.value = saved.totalTokens || 0;
    importedCardId.value = saved.importedCardId || null;
    // Restart timer with remaining time
    reviewRemainingMinutes.value = Math.ceil(remainingMs / 60000);
    reviewExpiryTimer = setTimeout(() => {
      reviewResult.value = null;
      improvements.value = [];
      clearReviewTimers();
      sessionStorage.removeItem(REVIEW_STORAGE_KEY);
    }, remainingMs);
    reviewCountdownTimer = setInterval(() => {
      if (reviewRemainingMinutes.value !== null && reviewRemainingMinutes.value > 1) {
        reviewRemainingMinutes.value--;
        saveReviewState();
      } else {
        clearReviewTimers();
      }
    }, 60000);
  } catch {
    sessionStorage.removeItem(REVIEW_STORAGE_KEY);
  }
}

function clearReviewTimers() {
  if (reviewExpiryTimer) { clearTimeout(reviewExpiryTimer); reviewExpiryTimer = null; }
  if (reviewCountdownTimer) { clearInterval(reviewCountdownTimer); reviewCountdownTimer = null; }
  reviewRemainingMinutes.value = null;
  sessionStorage.removeItem(REVIEW_STORAGE_KEY);
}

function startReviewExpiryTimer() {
  clearReviewTimers();
  reviewRemainingMinutes.value = 30;
  reviewExpiryTimer = setTimeout(() => {
    reviewResult.value = null;
    improvements.value = [];
    clearReviewTimers();
  }, REVIEW_TTL_MS);
  reviewCountdownTimer = setInterval(() => {
    if (reviewRemainingMinutes.value !== null && reviewRemainingMinutes.value > 1) {
      reviewRemainingMinutes.value--;
      saveReviewState();
    } else {
      clearReviewTimers();
    }
  }, 60 * 1000);
}

