function adjustTableHeight() {
  nextTick(() => {
    if (activeTab.value !== 'submissions') return;
    const container = containerRef.value;
    const tableArea = tableAreaRef.value;
    if (!container || !tableArea) return;
    const containerRect = container.getBoundingClientRect();
    const tableAreaRect = tableArea.getBoundingClientRect();
    const spaceAbove = tableAreaRect.top - containerRect.top;
    const available = containerRect.height - spaceAbove - 8;
    tableHeight.value = `${Math.max(available, 200)}px`;
  });
}

