// Parse card text into segments: plain text, translations, and variable badges
function parseCardText(card: any): { type: string; label: string }[] {
  const text = t.value(card.text);
  if (!text.includes('__%')) {
    return [{ type: 'text', label: text }];
  }
  const parts = text.split(/(__%)/);
  const segments: { type: string; label: string }[] = [];
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === '__%') {
      // Group: __% + id + __%
      const varId = parts[i + 1] || '';
      i += 2; // skip id and closing __%
      // Find variable display name
      const variable = (card.variables || []).find((v: any) => v.id === varId);
      const displayName = variable?.display_name || varId;
      const translated = t.value('wf_' + displayName);
      const label = translated !== 'wf_' + displayName
        ? translated
        : displayName.replace(/_/g, ' ');
      segments.push({ type: 'variable', label });
    } else if (parts[i].startsWith('trnsl_%')) {
      segments.push({ type: 'text', label: t.value(parts[i]) });
    } else if (parts[i].trim()) {
      segments.push({ type: 'text', label: parts[i] });
    }
  }
  return segments;
}

// Filtered cards based on active category + search
const filteredCards = computed(() => {
  let cards = allCardsForType.value;
  if (activeCategory.value) {
    cards = cards.filter((c: any) => c.category === activeCategory.value);
  }
  const needle = (cardSearchText.value || '').toLowerCase();
  if (needle) {
    cards = cards.filter((c: any) => {
      const segments = parseCardText(c);
      const fullText = segments.map((s) => s.label).join(' ').toLowerCase();
      const catText = t.value(c.category).toLowerCase();
      return fullText.includes(needle) || catText.includes(needle);
    });
  }
  return cards;
});

