function handleSSEEvent(event: Record<string, any>) {
  console.log('[SDK Review]', event.type, event);
  const type = event.type;

  switch (type) {
    case 'validation_stage':
      validationStages.value.push({
        stage: event.stage,
        passed: event.passed,
        errors: event.errors || [],
        warnings: event.warnings || [],
      });
      saveReviewState();
      break;

    case 'batch_start':
      currentBatch.value = event.batch;
      break;

    case 'agent_start':
      agentCards.value.push({
        id: event.agent_id,
        name: event.agent_name,
        icon: event.icon,
        status: 'running',
        content: '',
        severity: 'info',
        isGate: event.is_gate,
        batch: event.batch,
      });
      break;

    case 'agent_chunk': {
      const agent = agentCards.value.find(a => a.id === event.agent_id);
      if (agent) {
        agent.content += event.content;
      }
      break;
    }

    case 'agent_complete': {
      const agent = agentCards.value.find(a => a.id === event.agent_id);
      if (agent) {
        agent.status = event.passed ? 'passed' : 'failed';
        agent.severity = event.severity || 'info';
        if (event.error) agent.error = event.error as string;
      }
      saveReviewState();
      break;
    }

    case 'batch_complete':
      // No special handling needed
      break;

    case 'review_complete':
      reviewResult.value = {
        review_id: event.review_id || '',
        gates_passed: event.gates_passed,
        can_import: event.can_import,
        has_improvements: event.has_improvements || false,
      };
      startReviewExpiryTimer();
      saveReviewState();
      break;

    case 'usage':
      totalTokens.value = event.total_tokens || 0;
      saveReviewState();
      break;

    case 'ai_improvement':
      improvements.value.push({
        file: event.file as string,
        description: event.description as string,
        original: event.original as string,
        improved: event.improved as string,
      });
      saveReviewState();
      break;

    case 'error':
      notify.error(event.message || 'Review error');
      break;
  }
}

async function startReview() {
  if (!uploadFile.value) return;
  uploading.value = true;
  uploadResult.value = null;
  reviewResult.value = null;
  validationStages.value = [];
  agentCards.value = [];
  currentBatch.value = 0;
  totalTokens.value = 0;
  importedCardId.value = null;
  improvements.value = [];
  clearReviewTimers();

  try {
    const headers = await getHeaders();
    const formData = new FormData();
    formData.append('file', uploadFile.value);

    let response = await fetch(SDK_BASE + '/review', {
      method: 'POST',
      headers: {
        Authorization: headers.Authorization,
      },
      body: formData,
    });

    // On 401, refresh token and retry once
    if (response.status === 401) {
      const freshHeaders = await getHeaders();
      if (freshHeaders.Authorization && freshHeaders.Authorization !== headers.Authorization) {
        const retryFormData = new FormData();
        retryFormData.append('file', uploadFile.value);
        response = await fetch(SDK_BASE + '/review', {
          method: 'POST',
          headers: {
            Authorization: freshHeaders.Authorization,
          },
          body: retryFormData,
        });
      }
    }

    if (!response.ok) {
      const text = await response.text();
      uploadResult.value = { success: false, message: text || `HTTP ${response.status}` };
      return;
    }

    const reader = response.body?.getReader();
    if (!reader) return;

    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (!line.startsWith('data: ')) continue;
        const raw = line.slice(6);
        if (raw === '[DONE]') continue;
        try {
          const event = JSON.parse(raw);
          handleSSEEvent(event);
        } catch {
          // skip malformed JSON
        }
      }
    }

    // Process remaining buffer
    if (buffer.startsWith('data: ')) {
      const raw = buffer.slice(6);
      if (raw !== '[DONE]') {
        try {
          handleSSEEvent(JSON.parse(raw));
        } catch { /* skip */ }
      }
    }

    if (reviewResult.value?.gates_passed) {
      loadSubmissions();
    }
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Upload failed';
    uploadResult.value = { success: false, message: msg };
  } finally {
    uploading.value = false;
  }
}

async function downloadImprovedZip(reviewId: string) {
  try {
    const headers = await getHeaders();
    const res = await axios.get(SDK_BASE + '/review/' + reviewId + '/download', {
      headers,
      responseType: 'blob',
    });
    const url = window.URL.createObjectURL(new Blob([res.data]));
    const a = document.createElement('a');
    a.href = url;
    a.download = `improved-${reviewId.slice(0, 8)}.zip`;
    a.click();
    window.URL.revokeObjectURL(url);
  } catch (err: unknown) {
    const msg = axios.isAxiosError(err) && err.response?.data?.detail
      ? err.response.data.detail
      : 'Download failed';
    notify.error(msg);
  }
}

async function importReviewedCard(reviewId: string) {
  try {
    const headers = await getHeaders();
    // Try without file first — backend uses cached ZIP
    let res;
    try {
      res = await axios.post(
        SDK_BASE + '/review/' + reviewId + '/import',
        null,
        { headers },
      );
    } catch (firstErr: unknown) {
      // If backend says no file available and we have the original, retry with file upload
      if (
        axios.isAxiosError(firstErr) &&
        [400, 404].includes(firstErr.response?.status) &&
        uploadFile.value
      ) {
        const formData = new FormData();
        formData.append('file', uploadFile.value);
        res = await axios.post(
          SDK_BASE + '/review/' + reviewId + '/import',
          formData,
          { headers },
        );
      } else {
        throw firstErr;
      }
    }
    const cardsCreated = res.data?.cards_created;
    if (cardsCreated?.length) {
      importedCardId.value = cardsCreated[0].card_id;
    }
    notify.success(res.data?.message || 'Card imported successfully');
    uploadFile.value = null;
    loadSubmissions();
  } catch (err: unknown) {
    const msg =
      axios.isAxiosError(err) && err.response?.data?.detail
        ? err.response.data.detail
        : 'Import failed';
    notify.error(msg);
  }
}

async function importGithub() {
  importing.value = true;
  importResult.value = null;
  try {
    const headers = await getHeaders();
    const res = await axios.post(
      SDK_BASE + '/import-github',
      {
        url: githubUrl.value,
        branch: githubBranch.value || 'main',
        token: githubToken.value || null,
      },
      { headers },
    );
    importResult.value = res.data;
    githubToken.value = '';
    notify.success(t.value('import_success'));
    loadSubmissions();
  } catch (err: unknown) {
    const msg =
      axios.isAxiosError(err) && err.response?.data?.detail
        ? err.response.data.detail
        : t.value('import_failed');
    importResult.value = { success: false, message: msg };
  } finally {
    importing.value = false;
  }
}

function calculateOffset() {
  offset.value = pageSize.value * (currentPage.value - 1);
}

async function loadSubmissions() {
  loadingSubmissions.value = true;
  try {
    const headers = await getHeaders();
    const res = await axios.get(SDK_BASE + '/submissions', {
      headers,
      params: { offset: offset.value, per_page: pageSize.value },
    });
    submissions.value = res.data?.submissions || [];
    totalRecords.value = res.data?.total ?? 0;
  } catch {
    submissions.value = [];
    notify.error(t.value('load_submissions_failed'));
  } finally {
    loadingSubmissions.value = false;
  }
}

function handlePaginationChange(payload: { page: number; rowsPerPage: number }) {
  pageSize.value = payload.rowsPerPage;
  currentPage.value = payload.page;
  calculateOffset();
  loadSubmissions();
}

function confirmApprove(cardId: string, cardVersion?: number) {
  $q.dialog({
    title: t.value('confirm'),
    message: t.value('confirm_approve_card'),
    cancel: true,
    persistent: true,
  }).onOk(() => approve(cardId, cardVersion));
}

function confirmEnable(cardId: string, cardVersion: number) {
  $q.dialog({
    title: t.value('confirm'),
    message: t.value('confirm_enable_card'),
    cancel: true,
    persistent: true,
  }).onOk(() => setEnabled(cardId, cardVersion, true));
}

function confirmDisable(cardId: string, cardVersion: number) {
  $q.dialog({
    title: t.value('confirm'),
    message: t.value('confirm_disable_card'),
    cancel: true,
    persistent: true,
  }).onOk(() => setEnabled(cardId, cardVersion, false));
}

function confirmReject(cardId: string, cardVersion?: number) {
  $q.dialog({
    title: t.value('reject_card'),
    message: t.value('provide_rejection_reason'),
    prompt: {
      model: '',
      type: 'textarea',
      isValid: (val: string) => val.trim().length > 0,
    },
    cancel: true,
    persistent: true,
  }).onOk((reason: string) => reject(cardId, reason, cardVersion));
}

function confirmDelete(cardId: string, cardVersion?: number) {
  $q.dialog({
    title: t.value('confirm'),
    message: t.value('confirm_delete_card'),
    cancel: true,
    persistent: true,
  }).onOk(() => deleteSubmission(cardId, cardVersion));
}

function confirmBulkDelete() {
  const count = selectedSubmissions.value.length;
  $q.dialog({
    title: t.value('confirm'),
    message: t.value('bulk_delete_cards').replace('{count}', String(count)),
    cancel: true,
    persistent: true,
  }).onOk(async () => {
    try {
      const headers = await getHeaders();
      for (const sub of selectedSubmissions.value) {
        await axios.delete(SDK_BASE + '/submissions/' + sub.card_id, { headers });
      }
      notify.success(t.value('cards_deleted'));
      selectedSubmissions.value = [];
      loadSubmissions();
    } catch {
      notify.error(t.value('action_failed'));
    }
  });
}

async function deleteSubmission(cardId: string, cardVersion?: number) {
  actionLoading.value = true;
  try {
    const headers = await getHeaders();
    const config: Record<string, any> = { headers };
    if (cardVersion != null) config.data = { card_version: cardVersion };
    await axios.delete(SDK_BASE + '/submissions/' + cardId, config);
    notify.success(t.value('card_deleted'));
    loadSubmissions();
  } catch {
    notify.error(t.value('action_failed'));
  } finally {
    actionLoading.value = false;
  }
}

async function approve(cardId: string, cardVersion?: number) {
  actionLoading.value = true;
  try {
    const headers = await getHeaders();
    const body: Record<string, any> = {};
    if (cardVersion != null) body.card_version = cardVersion;
    await axios.post(
      SDK_BASE + '/submissions/' + cardId + '/approve',
      body,
      { headers },
    );
    notify.success(t.value('card_approved'));
    loadSubmissions();
  } catch {
    notify.error(t.value('action_failed'));
  } finally {
    actionLoading.value = false;
  }
}

async function setEnabled(cardId: string, cardVersion: number, enabled: boolean) {
  actionLoading.value = true;
  try {
    const headers = await getHeaders();
    await axios.post(
      SDK_BASE + '/submissions/' + cardId + '/set-enabled',
      { card_version: cardVersion, enabled },
      { headers },
    );
    notify.success(t.value(enabled ? 'card_enabled' : 'card_disabled'));
    loadSubmissions();
  } catch {
    notify.error(t.value('action_failed'));
  } finally {
    actionLoading.value = false;
  }
}

async function reject(cardId: string, reason?: string, cardVersion?: number) {
  actionLoading.value = true;
  try {
    const headers = await getHeaders();
    const body: Record<string, any> = {};
    if (reason) body.reason = reason;
    if (cardVersion != null) body.card_version = cardVersion;
    await axios.post(
      SDK_BASE + '/submissions/' + cardId + '/reject',
      body,
      { headers },
    );
    notify.success(t.value('card_rejected'));
    loadSubmissions();
  } catch {
    notify.error(t.value('action_failed'));
  } finally {
    actionLoading.value = false;
  }
}


onMounted(() => {
  restoreReviewState();
  loadSubmissions();
  // Load workflow cards if not already loaded
  if (!wfStore.workflowWhenCards?.length) {
    wfStore.loadWorkflowAllCards();
  }
  window.addEventListener('resize', adjustTableHeight);
  adjustTableHeight();
});

onBeforeUnmount(() => {
  clearReviewTimers();
  window.removeEventListener('resize', adjustTableHeight);
});
</script>

